create table if not exists public.educational_videos (id uuid primary key default gen_random_uuid(),slug text not null unique check(slug ~ '^[a-z0-9][a-z0-9-]{1,79}$'),title text not null check(char_length(title) between 3 and 140),description text not null default '' check(char_length(description)<=1200),youtube_video_id text not null check(youtube_video_id ~ '^[A-Za-z0-9_-]{11}$'),access_mode text not null default 'public' check(access_mode in ('public','unlisted','members')),is_published boolean not null default false,share_token uuid not null default gen_random_uuid(),play_starts bigint not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.educational_video_events(id bigint generated always as identity primary key,video_id uuid not null references public.educational_videos(id) on delete cascade,event_type text not null default 'play_start' check(event_type='play_start'),source text,medium text,campaign text,created_at timestamptz not null default now());
alter table public.educational_videos enable row level security; alter table public.educational_video_events enable row level security; revoke all on public.educational_videos,public.educational_video_events from anon,authenticated;
create index if not exists educational_video_events_video_created_idx on public.educational_video_events(video_id,created_at desc);
create or replace function public.list_public_educational_videos() returns jsonb language sql stable security definer set search_path='' as $$ select coalesce(jsonb_agg(jsonb_build_object('id',id,'slug',slug,'title',title,'description',description,'youtube_video_id',youtube_video_id,'play_starts',play_starts,'updated_at',updated_at) order by created_at desc),'[]'::jsonb) from public.educational_videos where is_published and access_mode='public'; $$;
revoke all on function public.list_public_educational_videos() from public; grant execute on function public.list_public_educational_videos() to anon,authenticated;
create or replace function public.get_educational_video(p_slug text,p_share_token uuid default null) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare v public.educational_videos%rowtype; allowed boolean:=false; begin select * into v from public.educational_videos where slug=p_slug and is_published; if not found then return null; end if; if v.access_mode='public' then allowed:=true; elsif v.access_mode='unlisted' then allowed:=p_share_token is not null and p_share_token=v.share_token; elsif v.access_mode='members' and auth.uid() is not null then select exists(select 1 from public.profiles where user_id=auth.uid() and account_status='approved') into allowed; end if; if not allowed then return null; end if; return jsonb_build_object('id',v.id,'slug',v.slug,'title',v.title,'description',v.description,'youtube_video_id',v.youtube_video_id,'access_mode',v.access_mode,'play_starts',v.play_starts); end; $$;
revoke all on function public.get_educational_video(text,uuid) from public; grant execute on function public.get_educational_video(text,uuid) to anon,authenticated;
create or replace function public.record_educational_video_play(p_slug text,p_share_token uuid default null,p_source text default null,p_medium text default null,p_campaign text default null) returns bigint language plpgsql security definer set search_path='' as $$ declare v public.educational_videos%rowtype; allowed boolean:=false; total bigint; begin select * into v from public.educational_videos where slug=p_slug and is_published for update; if not found then raise exception 'Video not found'; end if; if v.access_mode='public' then allowed:=true; elsif v.access_mode='unlisted' then allowed:=p_share_token is not null and p_share_token=v.share_token; elsif v.access_mode='members' and auth.uid() is not null then select exists(select 1 from public.profiles where user_id=auth.uid() and account_status='approved') into allowed; end if; if not allowed then raise exception 'Video access denied'; end if; update public.educational_videos set play_starts=play_starts+1 where id=v.id returning play_starts into total; insert into public.educational_video_events(video_id,source,medium,campaign) values(v.id,left(nullif(p_source,''),120),left(nullif(p_medium,''),120),left(nullif(p_campaign,''),160)); return total; end; $$;
revoke all on function public.record_educational_video_play(text,uuid,text,text,text) from public; grant execute on function public.record_educational_video_play(text,uuid,text,text,text) to anon,authenticated;
create or replace function public.owner_list_educational_videos() returns jsonb language plpgsql stable security definer set search_path='' as $$ begin if auth.uid() is null or not public.is_platform_owner() then raise exception 'Owner access required'; end if; return coalesce((select jsonb_agg(to_jsonb(v) order by v.created_at desc) from public.educational_videos v),'[]'::jsonb); end; $$;
revoke all on function public.owner_list_educational_videos() from public; grant execute on function public.owner_list_educational_videos() to authenticated;
create or replace function public.owner_upsert_educational_video(p_id uuid,p_slug text,p_title text,p_description text,p_youtube_video_id text,p_access_mode text,p_is_published boolean) returns jsonb language plpgsql security definer set search_path='' as $$ declare v public.educational_videos%rowtype; begin if auth.uid() is null or not public.is_platform_owner() then raise exception 'Owner access required'; end if; if p_slug !~ '^[a-z0-9][a-z0-9-]{1,79}$' or char_length(p_title) not between 3 and 140 or char_length(coalesce(p_description,''))>1200 or p_youtube_video_id !~ '^[A-Za-z0-9_-]{11}$' or p_access_mode not in ('public','unlisted','members') then raise exception 'Invalid video details'; end if; if p_id is null then insert into public.educational_videos(slug,title,description,youtube_video_id,access_mode,is_published) values(p_slug,p_title,coalesce(p_description,''),p_youtube_video_id,p_access_mode,p_is_published) returning * into v; else update public.educational_videos set slug=p_slug,title=p_title,description=coalesce(p_description,''),youtube_video_id=p_youtube_video_id,access_mode=p_access_mode,is_published=p_is_published,updated_at=now() where id=p_id returning * into v; if not found then raise exception 'Video not found'; end if; end if; return to_jsonb(v); end; $$;
revoke all on function public.owner_upsert_educational_video(uuid,text,text,text,text,text,boolean) from public; grant execute on function public.owner_upsert_educational_video(uuid,text,text,text,text,text,boolean) to authenticated;